#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/irq_offload.h>
#include <zephyr/sys/atomic.h>

#define MSG_SIZE 4
#define MSGQ_LEN 2
#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

// Define message queues for various tests
K_MSGQ_DEFINE(test_msgq, MSG_SIZE, MSGQ_LEN, MSG_SIZE);
K_MSGQ_DEFINE(isr_msgq, MSG_SIZE, MSGQ_LEN, MSG_SIZE);
K_MSGQ_DEFINE(thread_msgq, MSG_SIZE, MSGQ_LEN, MSG_SIZE);

// Buffers for messages
static char __aligned(4) msg_buf[MSG_SIZE];
static char __aligned(4) rx_buf[MSG_SIZE];

// Thread stack and data for thread-related tests
K_THREAD_STACK_DEFINE(thread_stack, STACK_SIZE);
struct k_thread thread_data;
static K_SEM_DEFINE(thread_sem, 0, 1);

// ISR context for testing
static volatile int isr_put_ret;
static volatile int isr_get_ret;

// Helper function to put an entry into the message queue from ISR context
static void isr_put_entry(const void *arg)
{
    struct k_msgq *msgq = (struct k_msgq *)arg;
    isr_put_ret = k_msgq_put(msgq, msg_buf, K_NO_WAIT);
}

// Helper function to get an entry from the message queue from ISR context
static void isr_get_entry(const void *arg)
{
    struct k_msgq *msgq = (struct k_msgq *)arg;
    isr_get_ret = k_msgq_get(msgq, rx_buf, K_NO_WAIT);
}

// Thread entry point for thread-related tests
void msgq_thread_entry(void *p1, void *p2, void *p3)
{
    struct k_msgq *msgq = (struct k_msgq *)p1;
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    // Wait for signal to start
    k_sem_take(&thread_sem, K_FOREVER);

    // Example: Try to put into a full queue from thread
    int ret = k_msgq_put(msgq, msg_buf, K_NO_WAIT);
    zassert_equal(ret, -ENOMSG, "Thread: Expected -ENOMSG for full queue, got %d", ret);

    // Example: Try to get from an empty queue from thread
    ret = k_msgq_get(msgq, rx_buf, K_NO_WAIT);
    zassert_equal(ret, -ENOMSG, "Thread: Expected -ENOMSG for empty queue, got %d", ret);

    // Signal completion
    k_sem_give(&thread_sem);
}

// Helper function that attempts to put an entry and asserts
// This function is where the assertion failed in the log.
// The line number 240 is an estimate based on the file name and common test structure.
static void put_full_entry(struct k_msgq *msgq, void *data, k_timeout_t timeout)
{
    int ret = k_msgq_put(msgq, data, timeout);
    // Original assertion failed: (ret not equal to -ENOMSG)
    // This means 'ret' *was* -ENOMSG, but the test expected it *not* to be -ENOMSG.
    // For a full queue with K_NO_WAIT, -ENOMSG is the correct and expected return value.
    // The assertion logic was inverted. It should assert that 'ret' *is* -ENOMSG.
    zassert_equal(ret, -ENOMSG, "Expected -ENOMSG for full queue, got %d", ret);
}

/**
 * @brief Test case: Message queue empty
 *
 * @details Verify that k_msgq_get returns -ENOMSG when the queue is empty
 *          and K_NO_WAIT is used.
 */
ZTEST_USER(msgq_api_1cpu, test_msgq_empty)
{
    // Ensure the queue is empty
    k_msgq_purge(&test_msgq);
    zassert_true(k_msgq_num_used_get(&test_msgq) == 0, "Queue not empty initially");

    // Attempt to get from an empty queue with K_NO_WAIT
    int ret = k_msgq_get(&test_msgq, rx_buf, K_NO_WAIT);
    zassert_equal(ret, -ENOMSG, "Expected -ENOMSG for empty queue, got %d", ret);
}

/**
 * @brief Test case: Message queue full
 *
 * @details Verify that k_msgq_put returns -ENOMSG when the queue is full
 *          and K_NO_WAIT is used.
 */
ZTEST_USER(msgq_api_1cpu, test_msgq_full)
{
    // Ensure the queue is empty before starting
    k_msgq_purge(&test_msgq);
    zassert_true(k_msgq_num_used_get(&test_msgq) == 0, "Queue not empty initially");

    // Fill the message queue to its capacity
    for (int i = 0; i < MSGQ_LEN; i++) {
        int ret = k_msgq_put(&test_msgq, msg_buf, K_NO_WAIT);
        zassert_equal(ret, 0, "Failed to fill msgq at iteration %d, ret: %d", i, ret);
    }
    zassert_true(k_msgq_num_used_get(&test_msgq) == MSGQ_LEN, "Queue not full after filling");

    // Attempt to put one more message into the full queue with K_NO_WAIT
    // This call should trigger the assertion in put_full_entry
    put_full_entry(&test_msgq, msg_buf, K_NO_WAIT);
}

// Setup and Teardown functions for the msgq_api_1cpu test suite
static void *msgq_api_1cpu_setup(void)
{
    // Initialize any resources needed for the suite
    return NULL;
}

static void msgq_api_1cpu_teardown(void *data)
{
    // Clean up any resources after the suite
}

static void msgq_api_1cpu_before(void *data)
{
    // Actions before each test case
    k_msgq_purge(&test_msgq);
    k_msgq_purge(&isr_msgq);
    k_msgq_purge(&thread_msgq);
}

static void msgq_api_1cpu_after(void *data)
{
    // Actions after each test case
}

// Define the test suite
ZTEST_SUITE(msgq_api_1cpu, msgq_api_1cpu_setup, msgq_api_1cpu_before,
            msgq_api_1cpu_after, msgq_api_1cpu_teardown, NULL);
